insert into private.player_account_links(player_id,user_id,verified_by,verification_reference) values('30000000-0000-0000-0000-000000000001','20000000-0000-0000-0000-000000000001','20000000-0000-0000-0000-000000000001','synthetic correction only');
set role authenticated;
set request.jwt.claim.sub='20000000-0000-0000-0000-000000000001';
do $$
declare a jsonb; sid uuid; fid uuid; otherid uuid; rev bigint; saved jsonb; op uuid; before_bad jsonb; original jsonb; other_frame jsonb;
 p uuid:='30000000-0000-0000-0000-000000000001'; q uuid:='30000000-0000-0000-0000-000000000002'; patch jsonb;
begin
 a:=app.start_session(gen_random_uuid(),'10000000-0000-0000-0000-000000000001','40000000-0000-0000-0000-000000000001','50000000-0000-0000-0000-000000000001',array[p,q],p);sid:=(a#>>'{session,id}')::uuid;
 a:=app.start_frame(gen_random_uuid(),sid,1,array[p,q],p);fid:=(a#>>'{frames,0,id}')::uuid;
 a:=app.complete_frame(gen_random_uuid(),sid,2,fid,p,0,0,false,'regular','TL');
 select to_jsonb(f)-array['winner_id','revision','special_event','potted_on_break','offender_id'] into original from app.frames f where id=fid;
 a:=app.start_frame(gen_random_uuid(),sid,3,array[p,q],q);otherid:=(select id from app.frames where session_id=sid and frame_number=2);
 select to_jsonb(f) into other_frame from app.frames f where id=otherid;
 -- Legacy argument list and same-key replay remain compatible, including request shape.
 op:=gen_random_uuid();a:=app.correct_frame(op,sid,4,fid,p,1,0,'Legacy');
 perform test.ok(app.correct_frame(op,sid,4,fid,p,1,0,'Legacy')=a,'old caller replay identical');
 perform test.ok((select special_event='regular' and not potted_on_break from app.frames where id=fid),'old caller preserves details');
 rev:=5;
 patch:=jsonb_build_object('special_event','golden_break','potted_on_break',false,'offender_id',null);
 before_bad:=app.get_session_state(sid);
 perform test.denied(format('select app.correct_frame(gen_random_uuid(),%L,%s,%L,%L,9,9,%L,%L::jsonb)',sid,rev,fid,p,'Invalid',patch),'23514','Golden Break without pot rejected');
 perform test.ok(app.get_session_state(sid)=before_bad,'invalid correction rolls back fouls and frame');
 patch:=jsonb_set(patch,'{potted_on_break}','true');op:=gen_random_uuid();
 a:=app.correct_frame(op,sid,rev,fid,p,1,0,'Edited saved frame',patch);rev:=rev+1;
 perform test.ok((select special_event='golden_break' and potted_on_break from app.frames where id=fid),'Normal to Golden Break');
 perform test.ok(app.correct_frame(op,sid,rev-1,fid,p,1,0,'Edited saved frame',patch)=a,'new correction idempotent');
 perform test.denied(format('select app.correct_frame(gen_random_uuid(),%L,%s,%L,%L,0,0,%L,%L::jsonb)',sid,rev,fid,q,'Invalid',patch),'23514','Golden Break nonbreaker rejected');
 patch:=jsonb_build_object('special_event','regular','potted_on_break',true,'offender_id',null);
 a:=app.correct_frame(gen_random_uuid(),sid,rev,fid,p,1,0,'Edited saved frame',patch);rev:=rev+1;
 perform test.ok((select special_event='regular' from app.frames where id=fid),'Golden Break to Normal');
 patch:=jsonb_build_object('special_event','super_foul','potted_on_break',true,'offender_id',p);
 perform test.denied(format('select app.correct_frame(gen_random_uuid(),%L,%s,%L,%L,0,0,%L,%L::jsonb)',sid,rev,fid,p,'Invalid',patch),'23514','offender cannot be winner');
 patch:=jsonb_set(patch,'{offender_id}','null');
 perform test.denied(format('select app.correct_frame(gen_random_uuid(),%L,%s,%L,%L,0,0,%L,%L::jsonb)',sid,rev,fid,p,'Invalid',patch),'23514','Super Foul needs explicit offender');
 patch:=jsonb_set(patch,'{offender_id}',to_jsonb(q));
 a:=app.correct_frame(gen_random_uuid(),sid,rev,fid,p,1,0,'Edited saved frame',patch);rev:=rev+1;
 perform test.ok((select special_event='super_foul' and offender_id=q from app.frames where id=fid),'Normal to Super Foul');
 patch:=jsonb_set(patch,'{special_event}','"regular"');
 perform test.denied(format('select app.correct_frame(gen_random_uuid(),%L,%s,%L,%L,0,0,%L,%L::jsonb)',sid,rev,fid,p,'Invalid',patch),'23514','stale offender rejected for Normal');
 patch:=jsonb_set(patch,'{offender_id}','null');a:=app.correct_frame(gen_random_uuid(),sid,rev,fid,p,1,0,'Edited saved frame',patch);rev:=rev+1;
 perform test.ok((select special_event='regular' and offender_id is null from app.frames where id=fid),'Super Foul to Normal explicitly clears offender');
 perform test.denied(format('select app.correct_frame(gen_random_uuid(),%L,%s,%L,%L,0,0,%L,%L::jsonb)',sid,rev,fid,p,'Invalid','{"special_event":"regular"}'),'22023','incomplete dependent fields rejected');
 perform set_config('request.jwt.claim.sub','20000000-0000-0000-0000-000000000004',true);
 perform test.denied(format('select app.correct_frame(gen_random_uuid(),%L,%s,%L,%L,0,0,%L,%L::jsonb)',sid,rev,fid,p,'Invalid',patch),'42501','unauthorized correction denied');
 perform set_config('request.jwt.claim.sub','20000000-0000-0000-0000-000000000001',true);
 perform test.ok((select to_jsonb(f)-array['winner_id','revision','special_event','potted_on_break','offender_id']=original from app.frames f where id=fid),'frame identity breaker duration and unrelated details unchanged');
 perform test.ok((select to_jsonb(f)=other_frame from app.frames f where id=otherid),'active unrelated frame unchanged');
 a:=app.complete_frame(gen_random_uuid(),sid,rev,otherid,q,0,0,false,'regular','BR');rev:=rev+1;
 patch:=jsonb_build_object('special_event','golden_break','potted_on_break',true,'offender_id',null);
 a:=app.correct_frame(gen_random_uuid(),sid,rev,fid,p,1,0,'Edited saved frame',patch);rev:=rev+1;
 a:=app.finalize_session(gen_random_uuid(),sid,rev);rev:=rev+1;
 perform test.ok((select count(*)=2 from app.frames where session_id=sid),'no duplicate frames');
 perform test.ok((select sum(value::int)=2 from jsonb_each_text(app.get_session_state(sid)->'scores')),'scores count corrected frame once');
 perform test.ok((select f->>'event'='golden_break' from jsonb_array_elements(app.get_my_frame_summary()->'nights') n cross join lateral jsonb_array_elements(n->'frames') f where f->>'id'=fid::text),'reloaded analytics reflects replacement event');
 perform test.denied(format('select app.correct_frame(gen_random_uuid(),%L,%s,%L,%L,0,0,%L,%L::jsonb)',sid,rev,fid,p,'Invalid',patch),'55000','finalized correction denied');
end $$;
reset role;
select test.ok((select count(*)=1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='app' and proname='correct_frame'),'one unambiguous RPC signature');
select test.ok(not has_function_privilege('anon','app.correct_frame(uuid,uuid,bigint,uuid,uuid,integer,integer,text,jsonb)','EXECUTE'),'anonymous execution denied');
